//! FORM target reflects exact authored browsing-context metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://control-names-input.test/submit><input id=area name=q value=Seed><input id=charset type=hidden name=_charset_ value=author><input id=submit type=submit value=sent></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://control-names-input.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_control_name_canonical_exact_once_conversion_and_raw_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'name');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get name'||a.set.name!=='set name'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'name')||x.name!=='')throw 'canonical';var calls=0;x.name={toString:function(){calls++;return '  UTF-8\ud800  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.name!=='  UTF-8\ud800  '||x.getAttributeNS(null,'name')!==x.name)throw 'exact raw';x.name=null;if(x.name!=='null')throw 'ordinary null';x.name=undefined;if(x.name!=='undefined')throw 'ordinary undefined';"#);}
#[test]
fn input_control_name_inert_exact_attribute_name_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','input');x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','upper');x.setAttributeNS(null,'Name','other');if(x.name!=='')throw 'exact key';x.name='A\ud800Z';var copy=x.cloneNode(false);copy.name='copy';if(x.name!=='A\ud800Z'||copy.name!=='copy'||copy.getAttributeNodeNS(null,'name')===x.getAttributeNodeNS(null,'name')||x.getAttributeNS('urn:foreign','name')!=='foreign'||x.getAttributeNS(null,'Name')!=='other')throw 'independent copy';"#);}

#[test]
fn input_control_name_keywords_remain_exact_metadata(){let(mut d,mut f,mut p)=fixture();for label in ["_self","_blank","_parent","_top","_unfencedTop","NamedFrame","  _SELF  ",""]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('submit');x.name='{label}';if(x.name!=='{label}'||x.getAttributeNS(null,'name')!=='{label}')throw 'exact target';"));}}
#[test]
fn input_control_name_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit');x.name='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.input_name_get(object).map(|_|())}else{bridge.input_name_set(object,&Value::String("growing-unknown-name-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.name='ON';if(x.name!=='ON'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn input_control_name_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),editor=document.getElementById('area');editor.value='Edited';x.name='on';var attribute=x.getAttributeNodeNS(null,'name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['name']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('name','OFF');","x.setAttributeNS(null,'name','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.name='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.name!=='OFF'||x.getAttributeNodeNS(null,'name')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='name'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('name');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.name!=='off\ud800'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn input_control_name_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'name'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-control-names-input.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://control-names-input.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.name!=='ON')throw 'fresh recovery';");}

#[test]
fn input_control_name_brand_abrupt_conversion_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),P=HTMLInputElement.prototype,a=Object.getOwnPropertyDescriptor(P,'name'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.name={toString:function(){calls++;x.name='inner';return ' OUTER ';}};if(calls!==1||x.name!==' OUTER ')throw 'once';var marker={};try{x.name={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.name!==' OUTER '||x.getAttribute('data-side')!=='kept')throw 'abrupt';Object.defineProperty(P,'name',{get:function(){return 'author';},configurable:true});a.set.call(x,'native');if(x.name!=='author'||a.get.call(x)!=='native')throw 'saved authority';delete P.name;if(x.name!==undefined)throw 'deleted canonical';Object.defineProperty(P,'name',a);var C=HTMLInputElement;delete window.HTMLInputElement;if(!(x instanceof C)||a.get.call(x)!=='native')throw 'saved constructor';"#);}


#[test]
fn input_control_name_wrong_interface_rejects_before_conversion_and_ordinary_receiver_reflects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'name'),calls=0,other=document.createElement('button');for(var bad of [other,document.getElementById('form')]){try{a.get.call(bad);throw 'getter brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'setter brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';var ordinary=document.createElement('input');ordinary.name=' _BLANK ';if(ordinary.name!==' _BLANK '||ordinary.getAttributeNS(null,'name')!==' _BLANK ')throw 'ordinary';document.getElementById('area').setAttribute('name','name');a.set.call(x);if(x.name!=='undefined'||a.get.call(x)!=='undefined')throw 'canonical neighbor and missing argument';");}

#[test]
fn native_control_name_lookup_raw_scalar_submission_alias_remove_and_reset(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let control=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("submit")).unwrap();let location=crate::navigation::address("https://control-names.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),raw=document.getElementsByName('A\ud800Z'),literal=document.getElementsByName('A\ufffdZ');x.name='A\ud800Z';if(x.name!=='A\ud800Z'||raw.length!==1||raw[0]!==x||literal.length!==0||document.getElementById('form')['A\ud800Z']!==x)throw 'exact live lookup';var attr=x.getAttributeNodeNS(null,'name');"#);assert_eq!(f.controls[&control].name,"A\u{fffd}Z");for(code,name,field)in[("","A\u{fffd}Z","A%EF%BF%BDZ=sent"),("attr.value='changed';","changed","changed=sent"),("x.removeAttributeNode(attr);","",""),("x.setAttributeNS(null,'name','restored');","restored","restored=sent")]{p.begin_job();run(&mut d,&mut f,&mut p,code);assert_eq!(f.controls[&control].name,name);let request=f.submit_request(&d,owner,Some(control),&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};let expected=format!("q=Seed&_charset_=UTF-8{}{}",if field.is_empty(){""}else{"&"},field);assert_eq!(body,expected.as_bytes());}f.reset_in_document(&d,owner).unwrap();assert_eq!(f.controls[&control].name,"restored");run(&mut d,&mut f,&mut p,"if(x.name!=='restored'||attr.ownerElement!==null||attr.value!=='changed')throw 'reset name identity';");}
#[test]
fn native_control_name_preserves_dirty_value_selection_flags_and_caption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),area=document.getElementById('area');area.value='Edited';var events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};");let control=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("submit")).unwrap();let editor=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&editor).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}let c=&f.controls[&control];let before=(c.value.text(),d.dom_attr(control,"value").map(|v|v.as_str().to_owned()),c.caption.clone(),c.checked,c.disabled,c.required,c.dirty_value,c.owner);run(&mut d,&mut f,&mut p,"x.name='new name';if(x.name!=='new name'||area.value!=='Edited'||events)throw 'metadata preserves native state';");let c=&f.controls[&control];assert_eq!((c.value.text(),d.dom_attr(control,"value").map(|v|v.as_str().to_owned()),c.caption.clone(),c.checked,c.disabled,c.required,c.dirty_value,c.owner),before);let e=&f.controls[&editor];assert_eq!((e.value.text(),e.value.cursor,e.value.anchor,e.value.offset,e.dirty_value),("Edited".into(),3,1,2,true));assert!(!p.has_navigation_request());}
